 const stable=[];for(const g of groups){if(g.count*hop<.1){const prev=stable.at(-1);if(prev)prev.count+=g.count;continue}const prev=stable.at(-1);if(prev?.midi===g.midi)prev.count+=g.count;else stable.push({...g})}
